// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint256 warpTime) public {
        vm.assume(blockNum > 0);
        vm.assume(warpTime > 0);
        vm.roll(blockNum);
        vm.warp(warpTime);
        address sender = address(0x1234);
        vm.deal(sender, 20 ether);
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "call failed");
        if (blockNum % 15 == 0) {
            assertEq(address(c).balance, 0 ether, "balance should be drained");
        } else {
            assertEq(address(c).balance, 10 ether, "balance should remain");
        }
    }
}
